@Entity
@Table(name = "accounts")
public class Account {
    @Id
    private String accountNumber;

    @Column(nullable = false)
    private Long balanceCents;

    @Version
    private Long version;

    public void debit(Long amount) {
        if (this.balanceCents < amount) {
            throw new InsufficientFundsException("Account has insufficient balance");
        }
        this.balanceCents -= amount;
    }

    public void credit(Long amount) {
        this.balanceCents += amount;
    }
}

@Service
public class TransferService {
    @Autowired
    private AccountRepository accountRepository;

    @Transactional
    public TransactionResult executeTransfer(String fromAcc, String toAcc, Long amount) {
        // Order locks lexicographically to prevent deadlocks
        String firstLock = fromAcc.compareTo(toAcc) < 0 ? fromAcc : toAcc;
        String secondLock = fromAcc.compareTo(toAcc) < 0 ? toAcc : fromAcc;

        Account source = accountRepository.findByAccountNumberForUpdate(fromAcc);
        Account destination = accountRepository.findByAccountNumberForUpdate(toAcc);

        source.debit(amount);
        destination.credit(amount);

        return new TransactionResult(UUID.randomUUID(), "COMPLETED");
    }
}
